-- Apenas clone descartável; usa COMMIT e duas sessões concorrentes.
do $$begin if current_database()<>'sso_foto_rr_0988_tmp' then raise exception 'banco_descartavel_exigido'; end if;end$$;
create extension if not exists pgtap with schema extensions;create extension if not exists dblink with schema extensions;set search_path=public,extensions;
select plan(4);
begin;set local app.auvo_sync_write='true';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('17988000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rr-tombstone@example.test',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17988000-0000-0000-0000-000000000001','colaborador','Teste RR',true);
insert into config.usuario_modulos(user_id,modulo,nivel) values ('17988000-0000-0000-0000-000000000001','pcm','escrita');
insert into pcm.clientes(id,nome,ativo,created_by) values ('17988000-0000-0000-0000-00000000000a','Cliente RR',true,'17988000-0000-0000-0000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17988000-0000-0000-0000-000000000001','cadastro.aprovar','17988000-0000-0000-0000-00000000000a');
insert into pcm.sso_levantamentos(id,cliente_id,origem,chave_origem,conteudo,criado_por) values ('17988000-0000-0000-0000-000000000021','17988000-0000-0000-0000-00000000000a','manual','rr-tombstone','[]','17988000-0000-0000-0000-000000000001');
insert into pcm.sso_levantamento_linhas(lote_id,chave,tipo,atributos) values ('17988000-0000-0000-0000-000000000021','a','sistema','{}');
update pcm.sso_ingestao_foto_gate set habilitado=true where id;update pcm.sso_fotos_levantamento_gate set habilitado=true where id;commit;
select extensions.dblink_connect('rr_a','dbname='||current_database());select extensions.dblink_connect('rr_b','dbname='||current_database());
select extensions.dblink_exec('rr_b','begin isolation level repeatable read');select extensions.dblink_exec('rr_b','set local application_name = ''s178_rr_b''');
select r from extensions.dblink('rr_b','select count(*)::integer from pcm.sso_ingestao_foto_reservas') as t(r integer);
select extensions.dblink_exec('rr_b','set local role service_role');
select extensions.dblink_exec('rr_a','begin');select extensions.dblink_exec('rr_a',$sql$set local request.jwt.claims='{"sub":"17988000-0000-0000-0000-000000000001","role":"authenticated","user_role":"colaborador"}'$sql$);select extensions.dblink_exec('rr_a','set local role authenticated');
select r from extensions.dblink('rr_a',$sql$select pcm.sso_cancelar_ingestao_foto('17988000-0000-0000-0000-00000000000a','17988000-0000-0000-0000-000000000041','17988000-0000-0000-0000-000000000021','a','Não recebido')$sql$) as t(r jsonb);
select extensions.dblink_send_query('rr_b',$sql$select pcm.sso_ingestao_foto_servico('reservar','17988000-0000-0000-0000-000000000001','17988000-0000-0000-0000-000000000041','17988000-0000-0000-0000-000000000021','a',repeat('a',64),null)$sql$);
select extensions.dblink_exec('rr_a','commit');
select count(*) from extensions.dblink_get_result('rr_b',false) as t(r jsonb);
select isnt(extensions.dblink_error_message('rr_b'),'OK','reserva tardia falha fechada mesmo em repeatable read');
select count(*) from extensions.dblink_get_result('rr_b',false) as t(r jsonb);select extensions.dblink_exec('rr_b','rollback');
select is((select count(*)::integer from pcm.sso_ingestao_foto_reservas where request_id='17988000-0000-0000-0000-000000000041'),0,'nenhuma reserva tardia');
select extensions.dblink_exec('rr_a','begin');select extensions.dblink_exec('rr_b','begin isolation level repeatable read');
select extensions.dblink_exec('rr_b','set local application_name = ''s178_rr_b''');
select r from extensions.dblink('rr_b','select count(*)::integer from pcm.sso_ingestao_foto_reservas') as t(r integer);
select extensions.dblink_exec('rr_b',$sql$set local request.jwt.claims='{"sub":"17988000-0000-0000-0000-000000000001","role":"authenticated","user_role":"colaborador"}'$sql$);select extensions.dblink_exec('rr_b','set local role authenticated');select extensions.dblink_exec('rr_a','set local role service_role');
select r from extensions.dblink('rr_a',$sql$select pcm.sso_ingestao_foto_servico('reservar','17988000-0000-0000-0000-000000000001','17988000-0000-0000-0000-000000000042','17988000-0000-0000-0000-000000000021','a',repeat('b',64),null)$sql$) as t(r jsonb);
select extensions.dblink_send_query('rr_b',$sql$select pcm.sso_cancelar_ingestao_foto('17988000-0000-0000-0000-00000000000a','17988000-0000-0000-0000-000000000042','17988000-0000-0000-0000-000000000021','a','Não recebido')$sql$);
select extensions.dblink_exec('rr_a','commit');select count(*) from extensions.dblink_get_result('rr_b',false) as t(r jsonb);
select isnt(extensions.dblink_error_message('rr_b'),'OK','cancelamento com snapshot antigo falha fechado');
select count(*) from extensions.dblink_get_result('rr_b',false) as t(r jsonb);select extensions.dblink_exec('rr_b','rollback');
select is((select count(*)::integer from pcm.sso_ingestao_foto_tombstones where request_id='17988000-0000-0000-0000-000000000042'),0,'não grava tombstone conflitante com reserva');
select extensions.dblink_disconnect('rr_a');select extensions.dblink_disconnect('rr_b');select * from finish();
